-- Issued reports (#147): the PDF generated by the server is kept in a private bucket, one row per report.
-- Members read (owner, commenter and reader alike see what was delivered); only the owner issues. Gone with the workspace.
create table public.report_history (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  title text not null,
  rules_version text not null,
  sections_hash text not null,
  storage_path text not null,
  size_bytes bigint not null,
  created_at timestamptz not null default now()
);
create index on public.report_history (workspace_id, created_at desc);

revoke all on public.report_history from anon;
alter table public.report_history enable row level security;
create policy report_history_select on public.report_history for select to authenticated using (public.is_member(workspace_id));
create policy report_history_insert on public.report_history for insert to authenticated
  with check (public.is_owner(workspace_id) and public.object_workspace(storage_path) = workspace_id);

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('reports', 'reports', false, 5242880, array['application/pdf'])
on conflict (id) do nothing;

create policy reports_objects_select on storage.objects for select to authenticated
  using (bucket_id = 'reports' and public.is_member(public.object_workspace(name)));
create policy reports_objects_insert on storage.objects for insert to authenticated
  with check (bucket_id = 'reports' and public.is_owner(public.object_workspace(name)));
